property.value:
let $unitOf := function($n) {
      $n/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration
        or self::CompactConstructorDeclaration or self::Initializer or self::LambdaExpression
        or self::FieldDeclaration or self::EnumConstant][1]
    },
    $typeOf := function($n) {
      $n/ancestor::*[self::ClassDeclaration or self::EnumDeclaration or self::RecordDeclaration
        or self::AnonymousClassDeclaration][1]
    },
    $memberOf := function($n) {
      $n/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration
        or self::CompactConstructorDeclaration or self::Initializer or self::FieldDeclaration][1]
    },
    $fields := function($t) { $t/*[self::ClassBody or self::EnumBody or self::RecordBody]/FieldDeclaration },
    $keyOf := function($e) as xs:string? {
      let $t := $typeOf($e), $names := $fields($t)/VariableDeclarator/VariableId/@Name
      return if ($e[self::ThisExpression][not(*)]) then 'this'
        else if ($e[self::ClassLiteral]) then string($e/ClassType/@SimpleName) || '.class'
        else if ($e[self::FieldAccess][*[1][self::ThisExpression][not(*)]][@Name = $names])
          then string($e/@Name)
        else if ($e[self::VariableAccess][@Name = $names][empty($memberOf($e)//VariableId[@Name = $e/@Name])])
          then string($e/@Name)
        else if ($e[self::FieldAccess]
                   [*[1][self::TypeExpression or self::AmbiguousName[matches(@Name, '^[A-Z]')]]])
          then (let $owner := string(($e/TypeExpression/ClassType/@SimpleName, $e/AmbiguousName/@Name)[1])
                return if ($owner = $t/@SimpleName and $e/@Name = $names) then string($e/@Name)
                  else $owner || '.' || $e/@Name)
        else ()
    },
    $isLock := function($call) as xs:boolean {
      exists($call[@MethodName = ('lock', 'lockInterruptibly')][ArgumentList/@Size = 0]
        [*[1][pmd-java:typeIs('java.util.concurrent.locks.Lock')]])
    },
    $held := function($n) {
      let $u := $unitOf($n)
      return (
        for $b in $n/ancestor::Block[parent::SynchronizedStatement][$unitOf(.) is $u]
        return ($keyOf($b/../*[1]), '?')[1],
        $u[self::MethodDeclaration][pmd-java:modifiers() = 'synchronized']
          /(if (pmd-java:modifiers() = 'static') then string($typeOf(.)/@SimpleName) || '.class' else 'this'),
        for $s in $n/ancestor-or-self::*[parent::Block][$unitOf(.) is $u],
            $l in $s/preceding-sibling::ExpressionStatement[MethodCall[$isLock(.)]]
        return let $k := $keyOf($l/MethodCall/*[1])
        return if (empty($k)) then '?'
          else if (exists($s/preceding-sibling::ExpressionStatement[. >> $l]
                     [MethodCall[@MethodName = 'unlock'][ArgumentList/@Size = 0][$keyOf(*[1]) = $k]])) then ()
          else $k)
    },
    $siteKey := function($s) {
      if ($s[self::SynchronizedStatement]) then $keyOf($s/*[1]) else $keyOf($s/MethodCall/*[1])
    },
    $sites := function($t) {
      $t//(SynchronizedStatement | ExpressionStatement[MethodCall[$isLock(.)]])[$typeOf(.) is $t]
    }
return //(SynchronizedStatement | ExpressionStatement[MethodCall[$isLock(.)]])
  [let $k := $siteKey(.), $t := $typeOf(.)
   return exists($k) and (some $h in $held(.)[. != '?'][. != $k] satisfies
     (some $other in $sites($t) satisfies $siteKey($other) = $h and $held($other) = $k))]

let $unitOf := function($n) {
      $n/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration
        or self::CompactConstructorDeclaration or self::Initializer or self::LambdaExpression
        or self::FieldDeclaration or self::EnumConstant][1]
    },
    $typeOf := function($n) {
      $n/ancestor::*[self::ClassDeclaration or self::EnumDeclaration or self::RecordDeclaration
        or self::AnonymousClassDeclaration][1]
    },
    $memberOf := function($n) {
      $n/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration
        or self::CompactConstructorDeclaration or self::Initializer or self::FieldDeclaration][1]
    },
    $fields := function($t) { $t/*[self::ClassBody or self::EnumBody or self::RecordBody]/FieldDeclaration },
    $keyOf := function($e) as xs:string? {
      let $t := $typeOf($e), $names := $fields($t)/VariableDeclarator/VariableId/@Name
      return if ($e[self::ThisExpression][not(*)]) then 'this'
        else if ($e[self::ClassLiteral]) then string($e/ClassType/@SimpleName) || '.class'
        else if ($e[self::FieldAccess][*[1][self::ThisExpression][not(*)]][@Name = $names])
          then string($e/@Name)
        else if ($e[self::VariableAccess][@Name = $names][empty($memberOf($e)//VariableId[@Name = $e/@Name])])
          then string($e/@Name)
        else if ($e[self::FieldAccess]
                   [*[1][self::TypeExpression or self::AmbiguousName[matches(@Name, '^[A-Z]')]]])
          then (let $owner := string(($e/TypeExpression/ClassType/@SimpleName, $e/AmbiguousName/@Name)[1])
                return if ($owner = $t/@SimpleName and $e/@Name = $names) then string($e/@Name)
                  else $owner || '.' || $e/@Name)
        else ()
    },
    $isLock := function($call) as xs:boolean {
      exists($call[@MethodName = ('lock', 'lockInterruptibly')][ArgumentList/@Size = 0]
        [*[1][pmd-java:typeIs('java.util.concurrent.locks.Lock')]])
    },
    $held := function($n) {
      let $u := $unitOf($n)
      return (
        for $b in $n/ancestor::Block[parent::SynchronizedStatement][$unitOf(.) is $u]
        return ($keyOf($b/../*[1]), '?')[1],
        $u[self::MethodDeclaration][pmd-java:modifiers() = 'synchronized']
          /(if (pmd-java:modifiers() = 'static') then string($typeOf(.)/@SimpleName) || '.class' else 'this'),
        for $s in $n/ancestor-or-self::*[parent::Block][$unitOf(.) is $u],
            $l in $s/preceding-sibling::ExpressionStatement[MethodCall[$isLock(.)]]
        return let $k := $keyOf($l/MethodCall/*[1])
        return if (empty($k)) then '?'
          else if (exists($s/preceding-sibling::ExpressionStatement[. >> $l]
                     [MethodCall[@MethodName = 'unlock'][ArgumentList/@Size = 0][$keyOf(*[1]) = $k]])) then ()
          else $k)
    },
    $concurrent := '^(Atomic|Concurrent|CopyOnWrite|(Long|Double)(Adder|Accumulator)$)|Blocking(Queue|Deque)$',
    $eligible := function($t) {
      $fields($t)[not(pmd-java:modifiers() = ('static', 'final'))]
        [not(ClassType[matches(@SimpleName, $concurrent)])]/VariableDeclarator/VariableId/@Name
    },
    $fieldOf := function($w) as xs:string? {
      let $target := $w/*[1], $names := $eligible($typeOf($w))
      return if ($target[self::FieldAccess][*[1][self::ThisExpression][not(*)]][@Name = $names])
          then string($target/@Name)
        else if ($target[self::VariableAccess][@Name = $names]
                   [empty($memberOf($w)//VariableId[@Name = $target/@Name])])
          then string($target/@Name)
        else ()
    },
    $writes := function($t) {
      $t//(AssignmentExpression | UnaryExpression[@Operator = ('++', '--')])
        [$typeOf(.) is $t][$unitOf(.)[self::MethodDeclaration]]
    },
    $single := function($w, $name) as xs:boolean {
      $w[self::AssignmentExpression][@Operator = '=']
        and empty($w/*[2]/descendant-or-self::*
          [self::VariableAccess or self::FieldAccess[*[1][self::ThisExpression]]][@Name = $name])
    },
    $calledLocked := function($m, $t) as xs:boolean {
      some $c in $t//MethodCall[@MethodName = $m/@Name][*[1][self::ArgumentList or self::ThisExpression]]
        [$typeOf(.) is $t]
      satisfies exists($held($c))
    }
return //(AssignmentExpression | UnaryExpression[@Operator = ('++', '--')])[$unitOf(.)[self::MethodDeclaration]]
  [let $t := $typeOf(.), $name := $fieldOf(.),
       $volatile := $fields($t)[pmd-java:modifiers() = 'volatile']/VariableDeclarator/VariableId/@Name
   return exists($name) and empty($held(.))
     and not($name = $volatile and $single(., $name))
     and not($calledLocked($unitOf(.), $t))
     and (some $w in $writes($t) satisfies $fieldOf($w) = $name and exists($held($w)[. != '?']))]
